package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonWriter_value_TriageGen0Test {

    private StringWriter stringWriter;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() throws IOException {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_WithNaN_ShouldThrowException() throws IOException {
        jsonWriter.value(Double.NaN);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_WithPositiveInfinity_ShouldThrowException() throws IOException {
        jsonWriter.value(Double.POSITIVE_INFINITY);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_WithNegativeInfinity_ShouldThrowException() throws IOException {
        jsonWriter.value(Double.NEGATIVE_INFINITY);
    }

    @Test
    public void testValue_WithFiniteValue_ShouldWriteValue() throws IOException {
        jsonWriter.value(123.456);
        assertEquals("{\"123.456\":true}", stringWriter.toString());
    }

    @Test
    public void testValue_WithZero_ShouldWriteValue() throws IOException {
        jsonWriter.value(0.0);
        assertEquals("{\"0.0\":true}", stringWriter.toString());
    }

    @Test
    public void testValue_WithNegativeValue_ShouldWriteValue() throws IOException {
        jsonWriter.value(-123.456);
        assertEquals("{\"-123.456\":true}", stringWriter.toString());
    }

    @Test
    public void testValue_WithMaxDouble_ShouldWriteValue() throws IOException {
        jsonWriter.value(Double.MAX_VALUE);
        assertEquals("{\"1.7976931348623157E308\":true}", stringWriter.toString());
    }

    @Test
    public void testValue_WithMinPositiveDouble_ShouldWriteValue() throws IOException {
        jsonWriter.value(Double.MIN_VALUE);
        assertEquals("{\"4.9E-324\":true}", stringWriter.toString());
    }

    @Test
    public void testValue_WithExactZero_ShouldWriteValue() throws IOException {
        jsonWriter.value(0.0);
        assertEquals("{\"0.0\":true}", stringWriter.toString());
    }

    @Test
    public void testValue_WithPrecision_ShouldWriteValue() throws IOException {
        jsonWriter.value(0.123456789);
        assertEquals("{\"0.123456789\":true}", stringWriter.toString());
    }
}
